#!/usr/bin/env python
"""
ANV EQ Quote Desk  -  RMS LOC/ACC builder, import, analysis and results in one workspace.

  Quote  ->  Geocode  ->  RMS run  ->  Results            (every account is saved to a library and can be re-opened)

SINGLE-FILE BUILD: the helper modules (rms_preflight, rms_results, rms_workbook, rms_pdf, anv_store, rms_results_ui)
are embedded below as compressed text and registered as normal Python modules at start-up, so ONLY this one file needs
uploading. Each module loads on its own, so a problem in one can never take down the rest of the app.

Keys can live in Streamlit Secrets / environment variables (LI_API_KEY, RISKDATA_API_KEY, GROUPING_API_KEY,
INFORCE_ANALYSIS_ID, RMS_HOST). The quote library is stored in STORE_DIR (default: a folder in the home directory).
"""
